       subtotalCents,
       discountCents,
       taxCents,
       shippingCents,
       totalCents: discountedSubtotal + taxCents + shippingCents,
     };
   }

   private async computeTotalsAsync(
     lines: readonly CartLine[],
     provider: AsyncTaxRateProvider,
   ): Promise<CartTotals> {
