describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 2000, costCents: 1000 },
      ],
      1500,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(calc.computeShippingCents([lineNoWeight("a", 3)], 5000)).toBe(0);
    });

    it("selects first bracket for weight within range", () => {
      expect(calc.computeShippingCents([line("a", 250)], 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(300);
    });

    it("selects next bracket when just over boundary", () => {
      expect(calc.computeShippingCents([line("a", 501)], 5000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      expect(calc.computeShippingCents([line("a", 2000)], 5000)).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(calc.computeShippingCents([line("a", 2001)], 5000)).toBe(1500);
    });

    it("uses heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      expect(noOverflow.computeShippingCents([line("a", 5000)], 5000)).toBe(600);
    });

    it("sums weights across multiple lines", () => {
      // 300 * 2 = 600g → second bracket
      expect(calc.computeShippingCents([line("a", 300, 2)], 5000)).toBe(600);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 1000 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      expect(unsorted.computeShippingCents([line("a", 400)], 5000)).toBe(300);
      expect(unsorted.computeShippingCents([line("a", 700)], 5000)).toBe(600);
    });
  });
});

