import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { CartLine, Product } from "../src/product.ts";
import type {
  PriceFetcher,
  InventoryChecker,
  InventoryDecision,
} from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (id: string, priceCents: number, weightGrams?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding the same product", () => {
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0].quantity).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product returning true", () => {
    cart.add(product("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity 0 removes the product", () => {
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("z", 5)).toThrow("Product z is not in the cart");
  });

  it("updateQuantity rejects negative", () => {
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 2000), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("snapshot is a deep copy", () => {
    cart.add(product("a", 1000), 2);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 1;
    expect(cart.snapshot()[0].quantity).toBe(2);
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal as sum of price * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500); // 2000 + 1500
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(300);
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps discount to subtotal (no negative totals)", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 500), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500); // clamped to subtotal
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      region: "US-CA",
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // taxable = 1000 - 200 = 800
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(totals.taxCents).toBe(80);
  });

  it("shipping receives lines and discounted subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900, // discounted subtotal
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=200, discounted=800, tax=80, shipping=500
    expect(totals.totalCents).toBe(800 + 80 + 500);
  });

  it("clamps negative tax to 0", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults region to US", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart — async checkout()", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(1500);
  });

  it("works without priceFetcher (uses cart prices)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("validates inventory and throws InventoryError on denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "only 2 left",
      } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
    }
  });

  it("throws InventoryError on partial-stock denial (available=true but qty insufficient)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
  });

  it("passes inventory check when available and qty sufficient", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      } satisfies InventoryDecision),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes when availableQuantity is not provided but available=true", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).resolves.toBeDefined();
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const cart = new Cart({ region: "FR" });
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.20),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    expect(result.totals.taxCents).toBe(200);
  });

  it("uses discount + asyncTax + shipping together", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
      region: "US",
    });
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal=1000, discount=200, discounted=800, tax=0.10*800=80, shipping=500
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(80);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(800 + 80 + 500);
  });

  it("propagates asyncTaxProvider failure", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("propagates priceFetcher failure", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service error")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service error");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({ region: "JP" });
    cart.add(product("a", 1000), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(800),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // refreshed price: 800 * 2 = 1600 subtotal, no discount, tax = 160, no shipping
    expect(result.totals.subtotalCents).toBe(1600);
    expect(result.totals.taxCents).toBe(160);
